@props([ 'name', 'label', 'currentFileUrl' => null, 'currentFileName' => 'ดูไฟล์ปัจจุบัน', ]) @php // Generate unique IDs for the input and preview elements $inputId = 'file_input_' . str_replace(['[]', '[', ']'], '', $name) . '_' . Str::random(4); $previewId = 'file_preview_' . str_replace(['[]', '[', ']'], '', $name) . '_' . Str::random(4); @endphp <div class="mb-3"> <label for="{{ $inputId }}" class="form-label">{{ $label }}</label> <div class="input-group"> <input type="file" class="form-control form-control-sm @error($name) is-invalid @enderror" id="{{ $inputId }}" name="{{ $name }}" accept="image/jpeg,image/png,image/gif,application/pdf" {{-- This event updates the preview when a file is *selected* --}} onchange=" const preview = document.getElementById('{{ $previewId }}'); if (this.files && this.files[0]) { const file = this.files[0]; preview.innerHTML = `<a href='${URL.createObjectURL(file)}' target='_blank' class='text-primary'><i class='bi bi-file-earmark-check'></i> ${file.name} (Ready to save)</a>`; } else { {{-- Revert to original file if selection is cancelled --}} @if($currentFileUrl) preview.innerHTML = `<a href='{{ $currentFileUrl }}' target='_blank'>{{ $currentFileName }}</a>`; @else preview.innerHTML = '<span class="text-muted small">ยังไม่ได้เลือกไฟล์</span>'; @endif } " > {{-- This is the new camera button --}} <button type="button" class="btn btn-outline-secondary" title="Use Camera" data-camera-btn data-camera-target="#{{ $inputId }}" data-camera-preview="#{{ $previewId }}" > <i class="bi bi-camera-fill"></i> </button> </div> <div class="file-upload-display mt-1" id="{{ $previewId }}"> @if($currentFileUrl) <a href="{{ $currentFileUrl }}" target="_blank">{{ $currentFileName }}</a> @else <span class="text-muted small">ยังไม่ได้เลือกไฟล์</span> @endif </div> @error($name) <div class="invalid-feedback d-block">{{ $message }}</div> @enderror </div>